/*
 * C++ exceptions for translated programs, after LLVM's Emscripten
 * exception lowering (opt -wasm-lower-em-ehsjlj): every invoke has
 * become a call through an __invoke_<sig> wrapper followed by a test
 * of __THREW__.  The wrappers (generated by mkinvoke.py) push a Frame
 * and setjmp; a throw longjmps to the innermost Frame.  Cleanups and
 * handlers are ordinary code in the translated program.
 *
 * This file is compiled by the target C compiler, not translated.
 */

typedef struct Ehframe Ehframe;
struct Ehframe
{
	jmp_buf	jb;
	Ehframe	*prev;
};

extern Ehframe	*eh_top;
extern long long	__THREW__;

void	*eh_match(void **types, int n);
